import Component from '@glimmer/component';
import { tracked } from '@glimmer/tracking';
import { on } from '@ember/modifier';
import { fn } from '@ember/helper';

const TABS = [
  { id: 'profile', label: 'Profile' },
  { id: 'notifications', label: 'Notifications' },
  { id: 'billing', label: 'Billing' },
];

const ZONES = [
  'Pacific/Honolulu (UTC−10:00)',
  'America/Anchorage (UTC−09:00)',
  'America/Los_Angeles (UTC−08:00)',
  'America/Denver (UTC−07:00)',
  'America/Chicago (UTC−06:00)',
  'America/New_York (UTC−05:00)',
  'America/Sao_Paulo (UTC−03:00)',
  'UTC (UTC±00:00)',
  'Europe/London (UTC±00:00)',
  'Europe/Berlin (UTC+01:00)',
  'Africa/Cairo (UTC+02:00)',
  'Asia/Dubai (UTC+04:00)',
  'Asia/Kolkata (UTC+05:30)',
  'Asia/Tokyo (UTC+09:00)',
  'Australia/Sydney (UTC+11:00)',
];

const NOTIFS = [
  { key: 'email', label: 'Email updates', desc: 'Product news and account activity sent to your inbox.' },
  { key: 'push', label: 'Push notifications', desc: 'Alerts on your phone and desktop.' },
  { key: 'sms', label: 'Text messages', desc: 'Security codes and urgent alerts only.' },
  { key: 'digest', label: 'Weekly digest', desc: 'A summary every Monday morning.' },
];

const PLANS = [
  { id: 'free', name: 'Free', price: '$0', desc: '1 project, community support' },
  { id: 'pro', name: 'Pro', price: '$12', desc: 'Unlimited projects, email support' },
  { id: 'team', name: 'Team', price: '$29', desc: 'Shared workspaces, SSO, priority support' },
];

export default class SettingsPage extends Component {
  @tracked selectedTab = 'profile';
  @tracked name = 'Maya Ortiz';
  @tracked email = 'maya.ortiz@example.com';
  @tracked timezone = 'America/Chicago (UTC−06:00)';
  @tracked notifs = { email: true, push: false, sms: false, digest: true };
  @tracked plan = 'pro';
  @tracked status = '';

  get tabs() {
    return TABS.map((t) => ({
      ...t,
      selected: t.id === this.selectedTab,
      tabindex: t.id === this.selectedTab ? '0' : '-1',
      tabId: `tab-${t.id}`,
      panelId: `panel-${t.id}`,
      hidden: t.id !== this.selectedTab,
    }));
  }

  get zones() {
    return ZONES.map((z) => ({ name: z, selected: z === this.timezone }));
  }

  get switches() {
    return NOTIFS.map((n) => ({
      ...n,
      on: this.notifs[n.key],
      labelId: `sw-${n.key}`,
      descId: `sw-d-${n.key}`,
    }));
  }

  get plans() {
    return PLANS.map((p) => ({
      ...p,
      checked: p.id === this.plan,
      tabindex: p.id === this.plan ? '0' : '-1',
    }));
  }

  get currentPlan() {
    return PLANS.find((p) => p.id === this.plan);
  }

  get profileHidden() { return this.selectedTab !== 'profile'; }
  get notificationsHidden() { return this.selectedTab !== 'notifications'; }
  get billingHidden() { return this.selectedTab !== 'billing'; }

  selectTab = (id) => {
    this.selectedTab = id;
  };

  onTabKey = (event) => {
    const keys = ['ArrowLeft', 'ArrowRight', 'Home', 'End'];
    if (!keys.includes(event.key)) return;
    event.preventDefault();
    const i = TABS.findIndex((t) => t.id === this.selectedTab);
    let n = i;
    if (event.key === 'ArrowRight') n = (i + 1) % TABS.length;
    if (event.key === 'ArrowLeft') n = (i - 1 + TABS.length) % TABS.length;
    if (event.key === 'Home') n = 0;
    if (event.key === 'End') n = TABS.length - 1;
    this.selectedTab = TABS[n].id;
    event.currentTarget.querySelectorAll('[role="tab"]')[n].focus();
  };

  setName = (e) => { this.name = e.target.value; };
  setEmail = (e) => { this.email = e.target.value; };
  setZone = (e) => { this.timezone = e.target.value; };

  toggle = (key) => {
    this.notifs = { ...this.notifs, [key]: !this.notifs[key] };
  };

  choosePlan = (id) => {
    this.plan = id;
  };

  onPlanKey = (event) => {
    const keys = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'];
    if (!keys.includes(event.key)) return;
    event.preventDefault();
    const i = PLANS.findIndex((p) => p.id === this.plan);
    let n = i;
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') n = (i + 1) % PLANS.length;
    if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') n = (i - 1 + PLANS.length) % PLANS.length;
    if (event.key === 'Home') n = 0;
    if (event.key === 'End') n = PLANS.length - 1;
    this.plan = PLANS[n].id;
    event.currentTarget.querySelectorAll('[role="radio"]')[n].focus();
  };

  save = (event) => {
    event.preventDefault();
    this.status = `Settings saved. Plan: ${this.currentPlan.name}, time zone: ${this.timezone}.`;
  };

  <template>
    <style>
      .settings { max-width: 40rem; margin: 1.5rem auto; font: 16px/1.5 system-ui, sans-serif; color: #1c2430; }
      .settings h1 { font-size: 1.5rem; margin: 0 0 1rem; }
      .settings [role="tablist"] { display: flex; gap: .25rem; border-bottom: 2px solid #d5dbe3; }
      .settings [role="tab"] { background: none; border: 0; padding: .6rem 1rem; font: inherit; cursor: pointer; border-bottom: 3px solid transparent; margin-bottom: -2px; color: #4a5565; }
      .settings [role="tab"][aria-selected="true"] { color: #0b4fb3; border-bottom-color: #0b4fb3; font-weight: 600; }
      .settings [role="tabpanel"] { padding: 1.25rem 0; }
      .settings :focus-visible { outline: 3px solid #f59e0b; outline-offset: 2px; }
      .settings label, .settings .lbl { display: block; font-weight: 600; margin: .75rem 0 .25rem; }
      .settings input, .settings select { width: 100%; box-sizing: border-box; padding: .5rem; font: inherit; border: 1px solid #8b95a5; border-radius: 6px; }
      .settings .row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .75rem 0; border-bottom: 1px solid #e6eaf0; }
      .settings .row p { margin: 0; color: #4a5565; font-size: .9rem; }
      .settings .row strong { display: block; }
      .settings [role="switch"] { flex: none; width: 3rem; height: 1.75rem; border-radius: 1rem; border: 2px solid #5b6577; background: #e6eaf0; position: relative; cursor: pointer; padding: 0; }
      .settings [role="switch"]::after { content: ""; position: absolute; top: 2px; left: 2px; width: 1.25rem; height: 1.25rem; border-radius: 50%; background: #5b6577; transition: transform .15s; }
      .settings [role="switch"][aria-checked="true"] { background: #0b4fb3; border-color: #0b4fb3; }
      .settings [role="switch"][aria-checked="true"]::after { transform: translateX(1.25rem); background: #fff; }
      .settings [role="radiogroup"] { display: grid; gap: .5rem; }
      .settings [role="radio"] { text-align: left; font: inherit; padding: .75rem 1rem; border: 2px solid #c3cad5; border-radius: 8px; background: #fff; cursor: pointer; display: flex; justify-content: space-between; gap: 1rem; }
      .settings [role="radio"][aria-checked="true"] { border-color: #0b4fb3; background: #eaf2ff; }
      .settings .price { font-weight: 700; }
      .settings .small { display: block; font-size: .875rem; color: #4a5565; font-weight: 400; }
      .settings .save { margin-top: 1rem; padding: .6rem 1.2rem; font: inherit; background: #0b4fb3; color: #fff; border: 0; border-radius: 6px; cursor: pointer; }
      .settings .status { min-height: 1.5rem; color: #0a6b35; margin-top: .5rem; }
    </style>

    <div class="settings">
      <h1>Settings</h1>
      <form {{on "submit" this.save}}>
        <div data-widget="tabs">
          <div role="tablist" aria-label="Settings sections" {{on "keydown" this.onTabKey}}>
            {{#each this.tabs as |t|}}
              <button
                type="button"
                role="tab"
                id={{t.tabId}}
                aria-selected={{if t.selected "true" "false"}}
                aria-controls={{t.panelId}}
                tabindex={{t.tabindex}}
                {{on "click" (fn this.selectTab t.id)}}
              >{{t.label}}</button>
            {{/each}}
          </div>

          <div role="tabpanel" id="panel-profile" aria-labelledby="tab-profile" tabindex="0" hidden={{this.profileHidden}}>
            <label for="f-name">Full name</label>
            <input id="f-name" type="text" autocomplete="name" value={{this.name}} {{on "input" this.setName}} />
            <label for="f-email">Email address</label>
            <input id="f-email" type="email" autocomplete="email" value={{this.email}} {{on "input" this.setEmail}} />
            <label for="f-tz">Time zone</label>
            <select id="f-tz" {{on "change" this.setZone}}>
              {{#each this.zones as |z|}}
                <option value={{z.name}} selected={{z.selected}}>{{z.name}}</option>
              {{/each}}
            </select>
          </div>

          <div role="tabpanel" id="panel-notifications" aria-labelledby="tab-notifications" tabindex="0" hidden={{this.notificationsHidden}}>
            {{#each this.switches as |s|}}
              <div class="row">
                <div>
                  <strong id={{s.labelId}}>{{s.label}}</strong>
                  <p id={{s.descId}}>{{s.desc}}</p>
                </div>
                <button
                  type="button"
                  role="switch"
                  data-widget="switch"
                  aria-checked={{if s.on "true" "false"}}
                  aria-labelledby={{s.labelId}}
                  aria-describedby={{s.descId}}
                  {{on "click" (fn this.toggle s.key)}}
                ></button>
              </div>
            {{/each}}
          </div>

          <div role="tabpanel" id="panel-billing" aria-labelledby="tab-billing" tabindex="0" hidden={{this.billingHidden}}>
            <div data-widget="radio-group">
              <div class="lbl" id="plan-label">Choose a plan</div>
              <div role="radiogroup" aria-labelledby="plan-label" {{on "keydown" this.onPlanKey}}>
                {{#each this.plans as |p|}}
                  <button
                    type="button"
                    role="radio"
                    aria-checked={{if p.checked "true" "false"}}
                    tabindex={{p.tabindex}}
                    {{on "click" (fn this.choosePlan p.id)}}
                  >
                    <span>{{p.name}}<span class="small">{{p.desc}}</span></span>
                    <span class="price">{{p.price}}/mo</span>
                  </button>
                {{/each}}
              </div>
            </div>
            <p>Current selection: <strong>{{this.currentPlan.name}}</strong>. Next invoice on 2026-12-14.</p>
          </div>
        </div>

        <button type="submit" class="save">Save changes</button>
        <div class="status" role="status" aria-live="polite">{{this.status}}</div>
      </form>
    </div>
  </template>
}

